-- SAE S3 Boggle - Module L2 - Jeu de test
-- en vrai la cle est dans la config du PHP
SET search_path = public, crypto;
\set cle 'cle_de_test'

-- crypt(..., gen_salt('bf')) simule password_hash() du PHP (password_verify accepte ce format)
SELECT inscrire('ali',   crypt('azerty', gen_salt('bf')),  'Ali@Test.fr',  :'cle');
SELECT inscrire('sarah', crypt('soleil', gen_salt('bf')),  'sarah@test.fr', :'cle');
SELECT inscrire('karim', crypt('boggle', gen_salt('bf')),  'karim@test.fr', :'cle');
SELECT inscrire('lea',   crypt('lea2026', gen_salt('bf')), NULL,            :'cle');

CALL modifier_identite(1, 'Khaloui', 'Ali', :'cle');
CALL modifier_profil(1, NULL, 'Fan de Boggle', TRUE);
-- les profils sont prives par defaut : sarah et lea choisissent de le rendre public, karim non
UPDATE profil SET est_public = TRUE WHERE joueur_id IN (2, 4);




