SELECT terminer_partie(2) IS NOT NULL AS partie_terminee;

-- pour avoir des dates differentes dans l'historique
UPDATE partie SET date_debut = date_debut - INTERVAL '2 days', date_fin = date_fin - INTERVAL '2 days',
       resultat = jsonb_set(resultat, '{date_debut}', to_jsonb(date_debut - INTERVAL '2 days'))
WHERE id = 1;

